	(833, '_transient_dash_v2_88ae138922fe95674369b1cb3d215a2b', '<div class="rss-widget"><ul><li><a class=\'rsswidget\' href=\'https://wordpress.org/news/2026/11/wordpress-7-1-5-release/\'>WordPress 7.1.5 Release</a></li><li><a class=\'rsswidget\' href=\'https://wordpress.org/news/2026/11/wordpress-7-2-release-candidate-1/\'>WordPress 7.2 Release Candidate 1</a></li></ul></div><div class="rss-widget"><ul><li><a class=\'rsswidget\' href=\'https://ma.tt/2026/11/tld-ideas/\'>Matt: TLD Ideas</a></li><li><a class=\'rsswidget\' href=\'https://openchannels.fm/what-to-expect-from-open-signal-podcast/\'>Open Channels FM: What to Expect from the Open Signal Podcast</a></li><li><a class=\'rsswidget\' href=\'https://odd.blog/2026/11/18/photo-competition-manager-0-4-0/\'>Donncha: Photo Competition Manager 0.4.0</a></li></ul></div>', 'off'),
