	(457, 1, '2026-11-20 11:32:51', '2026-11-20 11:32:51', '<div class="product-description has-more-content less-content table-responsive full-screen content-format" id="product-description" style="font-size: 16px; font-family: Roboto;  ">\n<div class="table-responsive full-screen mt-20">\n<table class="table table-bordered table-striped p_bottom_0" style="font-size: 16px; font-family: Roboto;">\n<tbody>\n<tr>\n<td>Tên sản phẩm</td>\n<td>Sữa chua Zott Montinis vị Táo 4*55g</td>\n</tr>\n<tr>\n<td>Thương hiệu</td>\n<td>Montinis</td>\n</tr>\n<tr>\n<td>Xuất xứ thương hiệu</td>\n<td>Đức</td>\n</tr>\n<tr>\n<td>Sản xuất tại</td>\n<td>Đức</td>\n</tr>\n<tr>\n<td>Trọng lượng sản phẩm</td>\n<td>220g (4 hộp x 55g)</td>\n</tr>\n<tr>\n<td>Độ tuổi phù hợp</td>\n<td>Trẻ em từ 6 tháng tuổi trở lên</td>\n</tr>\n<tr>\n<td>Nhà sản xuất</td>\n<td>Zott SE &amp; Co.KGBäumenheimer Str.25, 86690 Mertigen, Germany</td>\n</tr>\n<tr>\n<td>Thành phần</td>\n<td>Sữa chua (sữa tươi thanh trùng, men Streptococus thermophilus và Lactobacillus bulgaricus) (72%), đường, nước ép táo cô đặc (6,2%), chất xơ chiết xuất từ rễ rau diếp xoăn, chất ổn định (1422), bovine gelatine, hương liệu tự nhiên và tổng hợp dùng cho thực phẩm, vitamin C, vitamin B2, vitamin B6, vitamin B9Không sử dụng chất bảo quản</td>\n</tr>\n<tr>\n<td>Cảnh báo</td>\n<td>Không sử dụng sản phẩm khi đã hết hạn sử dụng</td>\n</tr>\n<tr>\n<td>Hướng dẫn sử dụng</td>\n<td>. Ăn trực tiếp;<br/>. Trẻ em từ 6 - 11 tháng: sử dụng 1/2 - 1 hộp mỗi ngày;<br/>. Trẻ em từ 1 tuổi trở lên: sử dụng 1-2 hộp mỗi ngày.</td>\n</tr>\n<tr>\n<td>Hướng dẫn bảo quản</td>\n<td>Bảo quản nhiệt độ 4-8 độ C</td>\n</tr>\n<tr>\n<td>Công ty nhập khẩu</td>\n<td>Công ty TNHH Zott Việt NamTầng 2, Tháp Tây, Tổ hợp công trình đa năng 28 tầng, Làng quốc tế Thăng Long, Phường Nghĩa Đô, Thành Phố Hà Nội, Việt Nam</td>\n</tr>\n<tr>\n<td>Hạn sử dụng</td>\n<td>210 ngày kể từ ngày sản xuất</td>\n</tr>\n</tbody>\n</table>\n</div>\n<div style="font-familys: Roboto !important; font-sizes: 1.0rem !important; font-weight: 400 !important; line-height: 1.4285714286 !important; color: #333333 !important; text-align: left;"> <div class="addclassfont16" style="font-sizes: 16px; font-familys: Helvetica;"><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span></div></div>\n</div>', 'Combo 2 Sữa chua Zott Montinis vị Táo 4*55g', 'Thương hiệu: Zott | Quy cách:', 'publish', 'open', 'closed', '', 'combo-2-sua-chua-zott-montinis-vi-tao-455g', '', '', '2026-11-20 11:32:51', '2026-11-20 11:32:51', '', 0, 'http://localhost/mammart/?product=combo-2-sua-chua-zott-montinis-vi-tao-455g', 0, 'product', '', 0),
