	(565, 1, '2026-11-20 11:33:32', '2026-11-20 11:33:32', '<div class="product-description has-more-content less-content table-responsive full-screen content-format" id="product-description" style="font-size: 16px; font-family: Roboto;  ">\n<div class="table-responsive full-screen mt-20">\n<table class="table table-bordered table-striped p_bottom_0" style="font-size: 16px; font-family: Roboto;">\n<tbody>\n<tr>\n<td>Tên sản phẩm</td>\n<td>Phô mai BelCube hương xoài chanh dây 78g</td>\n</tr>\n<tr>\n<td>Thương hiệu</td>\n<td>BELCUBE</td>\n</tr>\n<tr>\n<td>Xuất xứ thương hiệu</td>\n<td>Pháp</td>\n</tr>\n<tr>\n<td>Sản xuất tại</td>\n<td>Việt Nam</td>\n</tr>\n<tr>\n<td>Độ tuổi phù hợp</td>\n<td>Trẻ em và Người trưởng thành</td>\n</tr>\n<tr>\n<td>Thành phần</td>\n<td>Phô mai kem, sữa hoàn nguyên (nước, sữa bột), sirô đường, bơ, đạm sữa, tinh bột gạo, chất nhũ hóa: natri polyphosphat; trinatri citrat; tricalci orthophosphat, chất diều chỉnh độ acid: acid citric; hương liệu xoài chanh dây tự nhiên, chất tạo gel thạch aga; chất bảo quản kali sorbat, khoáng chất và vitamin (kali lodid, kẽm oxyd, vitamin A, vitamin D).</td>\n</tr>\n<tr>\n<td>Hướng dẫn bảo quản</td>\n<td>. Bảo quản nơi sạch sẽ, nhiệt độ 4-12 độ C<br/>. Tránh ánh nắng trực tiếp. Không cấp đông sản phẩm<br/>. Dùng hết sản phẩm trong vòng 1 tháng sau khi mở bao bì</td>\n</tr>\n<tr>\n<td>Hạn sử dụng</td>\n<td>6 tháng kể từ ngày sản xuất</td>\n</tr>\n</tbody>\n</table>\n</div>\n<div style="font-familys: Roboto !important; font-sizes: 1.0rem !important; font-weight: 400 !important; line-height: 1.4285714286 !important; color: #333333 !important; text-align: left;"><div class="addclassfont16" style="font-sizes: 16px; font-familys: Helvetica;"><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span><b>Hướng dẫn sử dụng</b></div><div style="font-sizes: 16px;	  font-familys: Helvetica;">\n<!--StartFragment--><div>. Sử dụng trực tiếp, ăn kèm thực phẩm khác hoặc chế biến các món ăn.<br/></div><!--EndFragment-->\n<div><span style="font-sizes: 16px;">﻿</span><span style="font-sizes: 16px;">﻿</span></div></div></div>\n</div>', 'Phô mai BelCube hương xoài chanh dây 78g', 'Thương hiệu: Con Bò Cười | Quy cách:', 'publish', 'open', 'closed', '', 'pho-mai-belcube-huong-xoai-chanh-day-78g', '', '', '2026-11-20 11:33:32', '2026-11-20 11:33:32', '', 0, 'http://localhost/mammart/?product=pho-mai-belcube-huong-xoai-chanh-day-78g', 0, 'product', '', 0),
