	(945, 1, '2026-11-20 11:36:04', '2026-11-20 11:36:04', '', 'dau-tram-cung-dinh-chuyen-dung-de-xong-100ml.webp', '', 'inherit', 'open', 'closed', '', 'dau-tram-cung-dinh-chuyen-dung-de-xong-100ml-webp', '', '', '2026-11-20 11:36:04', '2026-11-20 11:36:04', '', 0, 'http://localhost/mammart/wp-content/uploads/2026/11/dau-tram-cung-dinh-chuyen-dung-de-xong-100ml.webp', 0, 'attachment', 'image/webp', 0),
	(946, 1, '2026-11-20 11:36:05', '2026-11-20 11:36:05', '<div class="product-description has-more-content less-content table-responsive full-screen content-format" id="product-description" style="font-size: 16px; font-family: Roboto;  ">\n<div style="font-familys: Roboto !important; font-sizes: 1.0rem !important; font-weight: 400 !important; line-height: 1.4285714286 !important; color: #333333 !important; text-align: left;"><div class="addclassfont16" style="font-sizes: 16px; font-familys: Helvetica;"><b><span style="font-sizes: 16px;">﻿</span>Hướng dẫn bảo quản</b></div><div style="font-sizes: 16px;	  font-familys: Helvetica;"><p dir="ltr">Để nơi khô ráo, thoáng mát. </p><p dir="ltr">Tránh ánh sáng trực tiếp. </p><p dir="ltr">Tránh xa tầm tay trẻ em.</p><p><b><br/></b></p><p dir="ltr"><b>Thành phần chính</b></p><p dir="ltr">Tinh Dầu Tràm Gió</p><p dir="ltr">α-Terpineol……5-12%</p><p dir="ltr">Cineol ………..….74%</p><p><b><br/></b></p><p dir="ltr"><b>Lưu ý</b></p><p dir="ltr">Hòa tan với nước ấm khi bôi lên da cho trẻ sơ sinh hoặc trẻ nhỏ. </p><p><b><br/></b></p><p dir="ltr"><b>Chế độ bảo hành</b></p><p dir="ltr">Sản phẩm bị nứt vỡ, biến dạng.</p><p dir="ltr">Sản phẩm gần hết hạn hoặc quá hạn sử dụng và các lỗi khác do Nhà sản xuất.</p><p dir="ltr">Nếu lỗi do Nhà sản xuất chúng tôi sẽ chịu 100% chi phí cho việc đổi trả.</p><p><b><br/></b></p><p dir="ltr"><b>Thông tin sản phẩm</b></p><p dir="ltr">Tên sản phẩm: Dầu Xông Cung Đình</p><p dir="ltr">Thương hiệu: Cung Đình</p><p dir="ltr">Xuất xứ: Việt Nam</p><p dir="ltr">Nhà sản xuất: Chi Nhánh 1 - Công Ty Cổ Phần Dầu Tràm Cung Đình</p><p></p><p dir="ltr">Thể tích: 100ml﻿﻿</p><div></div></div></div>\n</div>', 'Dầu Xông Cung Đình (100ml)', 'Thương hiệu: Cung Đình | Quy cách:', 'publish', 'open', 'closed', '', 'dau-xong-cung-dinh-100ml', '', '', '2026-11-20 11:36:05', '2026-11-20 11:36:05', '', 0, 'http://localhost/mammart/?product=dau-xong-cung-dinh-100ml', 0, 'product', '', 0),
